/**
 * Progress through an ordered flow (`design/components/stepper.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/stepper.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import {
  Icon,
  MEMBER_PROVIDERS,
  Ref,
  agentMember,
  derived,
  elementRef,
  mountEffect,
  useMember,
  type Each,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/stepper.module.css'

export type StepperOrientation = NonNullable<StepperProps['orientation']>

export interface Step {
  label: string
  description?: string
  error?: boolean
}

export type StepperSpokenState = 'completed' | 'active' | 'upcoming' | 'error'

export type StepperSpoken = (step: {
  position: number
  count: number
  state: StepperSpokenState
}) => string

/** Progress through an ordered flow: the inputs it takes, by the React member's prop names. */
export interface StepperProps {
  /**
   * 0-based. Everything before it is completed, everything after it upcoming.
   */
  activeIndex: number
  orientation?: 'horizontal' | 'vertical'
  /**
   * Omit for the generic English sentence; localized hosts pass their own.
   */
  spoken?: StepperSpoken
  /**
   * Two to five; the spec says a flow with six steps needs a redesign.
   */
  steps: Step[]
}

/** Progress through an ordered flow. */
@Component({
  selector: 'pm-stepper',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref, Icon],
  // prettier-ignore
  template: `<ol
[attr.class]="e1()"
[attr.data-orientation]="e2()"
data-member="stepper"
[pmRef]="root"
>@for (row of e3(); track e4(row)) {<!-- step -->
<li
[attr.class]="e5()"
[attr.data-state]="e6(row)"
[attr.data-interactive]="e7(row)"
[attr.aria-current]="e8(row)"
>@switch (e24(row)) {
@case ('button') {<!-- control -->
<button
[attr.class]="e9()"
[attr.type]="e10(row)"
(click)="h1(row)"
><!-- indicator -->
<span
[attr.class]="e11()"
aria-hidden="true"
>@if (e12(row)) {<pm-icon
name="error"
size="sm"
></pm-icon>} @else if (e13(row)) {<span
[attr.class]="e14(row)"
><pm-icon
name="confirm"
size="sm"
></pm-icon></span>} @else {{{ e15(row) }}}</span>
<!-- copy -->
<span
[attr.class]="e16()"
><!-- label -->
<span
[attr.class]="e17()"
>{{ e18(row) }}</span>
@if (e19(row)) {<!-- description -->
<span
[attr.class]="e20(row)"
>{{ e21(row) }}</span>}
<!-- spoken -->
<span
[attr.class]="e22()"
>{{ e23(row) }}</span></span></button>}
@default {<!-- control -->
<span
[attr.class]="e9()"
[attr.type]="e10(row)"
(click)="h2(row)"
><!-- indicator -->
<span
[attr.class]="e11()"
aria-hidden="true"
>@if (e12(row)) {<pm-icon
name="error"
size="sm"
></pm-icon>} @else if (e13(row)) {<span
[attr.class]="e14(row)"
><pm-icon
name="confirm"
size="sm"
></pm-icon></span>} @else {{{ e15(row) }}}</span>
<!-- copy -->
<span
[attr.class]="e16()"
><!-- label -->
<span
[attr.class]="e17()"
>{{ e18(row) }}</span>
@if (e19(row)) {<!-- description -->
<span
[attr.class]="e20(row)"
>{{ e21(row) }}</span>}
<!-- spoken -->
<span
[attr.class]="e22()"
>{{ e23(row) }}</span></span></span>}
}
@if (e25(row)) {<!-- connector -->
<span
[attr.class]="e26(row)"
[attr.data-filled]="e27(row)"
></span>}</li>}</ol>`,
})
export class Stepper {
  /**
   * 0-based. Everything before it is completed, everything after it upcoming.
   */
  readonly activeIndex = input.required<StepperProps['activeIndex']>()
  readonly orientation = input<
    Exclude<StepperProps['orientation'], undefined>,
    StepperProps['orientation']
  >('horizontal', {
    transform: (value: StepperProps['orientation']) => (value === undefined ? 'horizontal' : value),
  })
  /**
   * Omit for the generic English sentence; localized hosts pass their own.
   */
  readonly spoken = input<Exclude<StepperProps['spoken'], undefined>, StepperProps['spoken']>(
    ({ position, count, state }: Parameters<StepperSpoken>[0]) =>
      `step ${position} of ${count}, ${{ completed: 'completed', active: 'current', upcoming: 'not started', error: 'error' }[state]}`,
    {
      transform: (value: StepperProps['spoken']) =>
        value === undefined
          ? ({ position, count, state }: Parameters<StepperSpoken>[0]) =>
              `step ${position} of ${count}, ${{ completed: 'completed', active: 'current', upcoming: 'not started', error: 'error' }[state]}`
          : value,
    },
  )
  /**
   * Two to five; the spec says a flow with six steps needs a redesign.
   */
  readonly steps = input.required<StepperProps['steps']>()
  /**
   * Renders completed steps as buttons. Active and upcoming stay static.
   */
  readonly onStepSelect = output<number>({ alias: 'stepSelect' })
  protected readonly $ = useMember({
    events: ['stepSelect'],
    props: {
      activeIndex: () => this.activeIndex(),
      orientation: () => this.orientation(),
      spoken: () => this.spoken(),
      steps: () => this.steps(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly root = elementRef<HTMLElement>()
  protected readonly rows = derived(() =>
    this.$p.steps.map((step, index) =>
      ((walk: 'completed' | 'active' | 'upcoming') => ({
        step,
        index,
        walk,
        state: step.error === true ? ('error' as const) : walk,
      }))(
        index < this.$p.activeIndex
          ? 'completed'
          : index === this.$p.activeIndex
            ? 'active'
            : 'upcoming',
      ),
    ),
  )
  private release1: (() => void) | undefined

  constructor() {
    inject(DestroyRef).onDestroy(() => this.release1?.())
    mountEffect(() => this.effect1())
  }

  protected e1() {
    return styles.root
  }

  protected e2() {
    return this.$p.orientation
  }

  e3() {
    return this.rows.value
  }

  protected e4(row: Each<ReturnType<Stepper['e3']>>) {
    return row.index
  }

  protected e5() {
    return styles.step
  }

  protected e6(row: Each<ReturnType<Stepper['e3']>>) {
    return row.state
  }

  protected e7(row: Each<ReturnType<Stepper['e3']>>) {
    return row.walk === 'completed' && this.$.listening(this.onStepSelect, 'onStepSelect')
      ? ''
      : undefined
  }

  protected e8(row: Each<ReturnType<Stepper['e3']>>) {
    return row.walk === 'active' ? 'step' : undefined
  }

  protected e9() {
    return styles.control
  }

  protected e10(row: Each<ReturnType<Stepper['e3']>>) {
    return row.walk === 'completed' && this.$.listening(this.onStepSelect, 'onStepSelect')
      ? 'button'
      : undefined
  }

  protected h1(row: Each<ReturnType<Stepper['e3']>>): void {
    if (row.walk === 'completed' && this.$.listening(this.onStepSelect, 'onStepSelect')) {
      this.$.emit(this.onStepSelect, 'onStepSelect', row.index)
    }
  }

  protected e11() {
    return styles.indicator
  }

  protected e12(row: Each<ReturnType<Stepper['e3']>>) {
    return row.state === 'error'
  }

  protected e13(row: Each<ReturnType<Stepper['e3']>>) {
    if (row.state === 'error') return undefined as never
    return row.state === 'completed'
  }

  protected e14(row: Each<ReturnType<Stepper['e3']>>) {
    if (row.state === 'error') return undefined as never
    if (!(row.state === 'completed')) return undefined as never
    return styles.check
  }

  protected e15(row: Each<ReturnType<Stepper['e3']>>) {
    if (row.state === 'error') return undefined as never
    if (row.state === 'completed') return undefined as never
    return row.index + 1
  }

  protected e16() {
    return styles.copy
  }

  protected e17() {
    return styles.label
  }

  protected e18(row: Each<ReturnType<Stepper['e3']>>) {
    return row.step.label
  }

  protected e19(row: Each<ReturnType<Stepper['e3']>>) {
    return row.step.description !== undefined
  }

  protected e20(row: Each<ReturnType<Stepper['e3']>>) {
    if (!(row.step.description !== undefined)) return undefined as never
    return styles.description
  }

  protected e21(row: Each<ReturnType<Stepper['e3']>>) {
    if (!(row.step.description !== undefined)) return undefined as never
    return row.step.description
  }

  protected e22() {
    return styles.spoken
  }

  protected e23(row: Each<ReturnType<Stepper['e3']>>) {
    return `, ${this.$p.spoken({ position: row.index + 1, count: this.$p.steps.length, state: row.state })}`
  }

  protected h2(row: Each<ReturnType<Stepper['e3']>>): void {
    if (row.walk === 'completed' && this.$.listening(this.onStepSelect, 'onStepSelect')) {
      this.$.emit(this.onStepSelect, 'onStepSelect', row.index)
    }
  }

  protected e24(row: Each<ReturnType<Stepper['e3']>>) {
    return row.walk === 'completed' && this.$.listening(this.onStepSelect, 'onStepSelect')
      ? 'button'
      : 'span'
  }

  protected e25(row: Each<ReturnType<Stepper['e3']>>) {
    return row.index !== this.$p.steps.length - 1
  }

  protected e26(row: Each<ReturnType<Stepper['e3']>>) {
    if (!(row.index !== this.$p.steps.length - 1)) return undefined as never
    return styles.connector
  }

  protected e27(row: Each<ReturnType<Stepper['e3']>>) {
    if (!(row.index !== this.$p.steps.length - 1)) return undefined as never
    return row.walk === 'completed' ? '' : undefined
  }

  private effect1(): void {
    this.release1?.()
    const ran = agentMember({
      member: 'Stepper',
      element: () => this.root.value,
      state: () => ({
        'active-index': this.$p.activeIndex,
        steps: this.rows.value.map((row) => ({ label: row.step.label, state: row.state })),
      }),
      actions: {
        set: {
          argument: 'number',
          run: (value) =>
            (() => {
              if (!this.$.listening(this.onStepSelect, 'onStepSelect'))
                throw new Error('These steps are not revisitable.')
              if (!Number.isInteger(value) || value < 0 || value >= this.$p.activeIndex) {
                throw new Error(`Step ${value} is not a completed step, so it cannot be revisited.`)
              }
              this.$.emit(this.onStepSelect, 'onStepSelect', value)
            })(),
        },
      },
    })
    this.release1 = () => {
      ran()
    }
  }
}
